CREATE OR REPLACE FUNCTION public.duplicate_campaign(p_campaign_id uuid) RETURNS public.campaigns LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE source public.campaigns; result public.campaigns; a public.ads; v public.campaign_versions; copied_id uuid; ids jsonb:='{}'::jsonb; snapshots jsonb; item jsonb; old_id text; BEGIN SELECT * INTO source FROM public.campaigns WHERE id=p_campaign_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF; INSERT INTO public.campaigns(user_id,name,status,platform,budget,objective,start_date,end_date,target_audience,settings) VALUES(auth.uid(),source.name||' (Copy)','draft',source.platform,source.budget,source.objective,source.start_date,source.end_date,source.target_audience,source.settings) RETURNING * INTO result; FOR a IN SELECT * FROM public.ads WHERE campaign_id=source.id AND user_id=auth.uid() LOOP copied_id:=gen_random_uuid(); ids:=ids||jsonb_build_object(a.id::text,copied_id); INSERT INTO public.ads(id,user_id,campaign_id,template_id,content,preview_url,canvas_data,name,status) VALUES(copied_id,auth.uid(),result.id,a.template_id,a.content,a.preview_url,a.canvas_data,a.name,'draft'); END LOOP; FOR v IN SELECT * FROM public.campaign_versions WHERE campaign_id=source.id AND user_id=auth.uid() ORDER BY version_number LOOP snapshots:='[]'::jsonb; FOR item IN SELECT * FROM jsonb_array_elements(v.snapshot->'creatives') LOOP old_id:=item->>'id'; IF NOT ids ? old_id THEN ids:=ids||jsonb_build_object(old_id,gen_random_uuid()); END IF; item:=jsonb_set(jsonb_set(item,'{id}',ids->old_id),'{campaign_id}',to_jsonb(result.id)); snapshots:=snapshots||jsonb_build_array(item); END LOOP; INSERT INTO public.campaign_versions(campaign_id,user_id,version_number,label,description,snapshot) VALUES(result.id,auth.uid(),v.version_number,v.label,v.description,jsonb_build_object('campaign',jsonb_set(v.snapshot->'campaign','{id}',to_jsonb(result.id)),'creatives',snapshots)); END LOOP; RETURN result; END $$;